#!/usr/bin/env bash
set -Eeuo pipefail
export AB_PAYLOAD=''
export AB_SHA='e0f9fc0c8e755bcf78dc6a32bc8619452e5acfd16d91403d6cb3e3cde5005137'
for c in python3 tar base64 sha256sum mktemp; do command -v "$c" >/dev/null || { echo "Manca $c" >&2; exit 1; }; done
AB_TMP=$(mktemp -d "${TMPDIR:-/tmp}/zdos-ab.XXXXXXXX")
trap 'rm -rf -- "$AB_TMP"' EXIT
printf '%s' "$AB_PAYLOAD" | base64 -d > "$AB_TMP/bundle.tar.xz"
printf '%s  %s\n' "$AB_SHA" "$AB_TMP/bundle.tar.xz" | sha256sum -c - >/dev/null
python3 - "$AB_TMP" <<'PYSAFE'
import pathlib,sys,tarfile
p=pathlib.Path(sys.argv[1])
with tarfile.open(p/'bundle.tar.xz','r:xz') as t:
 for m in t.getmembers():
  n=pathlib.PurePosixPath(m.name)
  if n.is_absolute() or '..' in n.parts or not (m.isfile() or m.isdir()): raise SystemExit('Archivio non sicuro')
 t.extractall(p/'bundle')
PYSAFE
bash "$AB_TMP/bundle/engine.sh" "$@"
